  it('should delete an article', async () => {
    const deleteResponse = await request(APP_URL)
      .delete(`/api/v1/articles/${articleId}`)
      .auth(session.token, { type: 'bearer' });
    expect([200, 204]).toContain(deleteResponse.status);
  });
});

